import React, { useState, useEffect, useRef } from 'react';
import './App.css';
import Documentation from './Documentation';
const tfModule = await import('@tensorflow/tfjs');
let tf = tfModule.default || tfModule;
const tfvisModule = await import('@tensorflow/tfjs-vis');
let tfvis = tfvisModule.default || tfvisModule;

const SEQ_LEN = 5;
const NUM_EPOCHS = 1;
const BATCH_SIZE = 32;
const LEARNING_RATE = 0.01;
const DEFAULT_TEMPERATURE = 0.8;
const DEFAULT_TOPK = 5;
const SUGGESTION_COUNT = 5;

function tokenize(text) {
  const cleaned = text.toLowerCase().replace(/[^a-zA-Z\s]/g, '');
  return cleaned.split(/\s+/).filter(w => w.length > 0);
}

function buildVocab(tokens) {
  const set = Array.from(new Set(tokens));
  const word2idx = {};
  set.forEach((w, i) => { word2idx[w] = i; });
  return { word2idx, idx2word: set };
}

async function loadData() {
  const resp = await fetch('data.txt');
  const text = await resp.text();
  const tokens = tokenize(text);
  const vocab = buildVocab(tokens);
  const sequences = [];
  const labels = [];
  for (let i = 0; i < tokens.length - SEQ_LEN; i++) {
    const seq = tokens.slice(i, i + SEQ_LEN);
    const label = tokens[i + SEQ_LEN];
    sequences.push(seq.map(w => vocab.word2idx[w]));
    labels.push(vocab.word2idx[label]);
  }
  return { sequences, labels, vocab };
}

async function trainModel(data) {
  // Helper to compute top-K accuracy
  async function evaluateTopK(model, sequences, labels, k) {
    const xsEval = tf.tensor2d(sequences);
    const preds = model.predict(xsEval);
    // get top-k indices for each example
    const { indices } = tf.topk(preds, k);
    const topk = await indices.array();
    xsEval.dispose(); preds.dispose(); indices.dispose();
    let correct = 0;
    topk.forEach((row, idx) => {
      if (row.includes(labels[idx])) correct++;
    });
    return correct / labels.length;
  }

  const { sequences, labels, vocab } = data;
  const xs = tf.tensor2d(sequences);
  const ys = tf.oneHot(tf.tensor1d(labels, 'int32'), vocab.idx2word.length);

  const model = tf.sequential();
  model.add(tf.layers.embedding({ inputDim: vocab.idx2word.length, outputDim: 64, inputLength: SEQ_LEN }));
  model.add(tf.layers.lstm({ units: 100, returnSequences: true }));
  model.add(tf.layers.lstm({ units: 100 }));
  model.add(tf.layers.dense({ units: vocab.idx2word.length, activation: 'softmax' }));

  const optimizer = tf.train.adam(LEARNING_RATE);
  // Compile model tracking loss only
  model.compile({ optimizer, loss: 'categoricalCrossentropy' });

  // Prepare visualization callbacks for loss
  const metricsSurface = { name: 'Training Metrics', tab: 'Training' };
  const visCallback = tfvis.show.fitCallbacks(metricsSurface, ['loss']);

  // Prepare an array to accumulate perplexity values over epochs
  const perplexityValues = [];
  const perplexitySurface = { name: 'Perplexity', tab: 'Training' };
  const perplexityCallback = {
    onEpochEnd: async (epoch, logs) => {
      const perplexity = Math.exp(logs.loss);
      perplexityValues.push({ x: epoch + 1, y: perplexity });
      tfvis.render.linechart(
        perplexitySurface,
        { values: perplexityValues },
        { xLabel: 'Epoch', yLabel: 'Perplexity' }
      );
    }
  };

  // Prepare an array to accumulate Top-K accuracy over epochs
  const topkValues = [];
  const accSurface = { name: `Top-${SUGGESTION_COUNT} Accuracy`, tab: 'Training' };
  const topkCallback = {
    onEpochEnd: async (epoch, logs) => {
      const acc = await evaluateTopK(model, sequences, labels, SUGGESTION_COUNT);
      topkValues.push({ x: epoch + 1, y: acc });
      tfvis.render.linechart(
        accSurface,
        { values: topkValues },
        { xLabel: 'Epoch', yLabel: 'Accuracy' }
      );
    }
  };

  const topkValues2 = [];
  const accSurface2 = { name: `Top-1 Accuracy`, tab: 'Training' };
  const topkCallback2 = {
    onEpochEnd: async (epoch, logs) => {
      const acc = await evaluateTopK(model, sequences, labels, 1);
      topkValues2.push({ x: epoch + 1, y: acc });
      tfvis.render.linechart(
        accSurface2,
        { values: topkValues2 },
        { xLabel: 'Epoch', yLabel: 'Accuracy' }
      );
    }
  };

  const topkValues3 = [];
  const accSurface3 = { name: `Top-10 Accuracy`, tab: 'Training' };
  const topkCallback3 = {
    onEpochEnd: async (epoch, logs) => {
      const acc = await evaluateTopK(model, sequences, labels, 10);
      topkValues3.push({ x: epoch + 1, y: acc });
      tfvis.render.linechart(
        accSurface3,
        { values: topkValues3 },
        { xLabel: 'Epoch', yLabel: 'Accuracy' }
      );
    }
  };

  // Train model with loss, perplexity and top-K accuracy callbacks
  await model.fit(xs, ys, {
    epochs: NUM_EPOCHS,
    batchSize: BATCH_SIZE,
    callbacks: [visCallback, perplexityCallback, topkCallback, topkCallback2, topkCallback3]
  });
  await model.fit(xs, ys, {
    epochs: NUM_EPOCHS,
    batchSize: BATCH_SIZE,
    callbacks: [visCallback, perplexityCallback]
  });

  // Return trained model and vocab so App can proceed
  xs.dispose();
  ys.dispose();
  return { model, vocab };
}

async function sampleNextWord(model, inputSeq, vocab, temperature = DEFAULT_TEMPERATURE, topKFilter = DEFAULT_TOPK) {
  const input = tf.tensor2d([inputSeq]);
  const logits = tf.log(model.predict(input));
  const adjusted = tf.div(logits, temperature);
  const values = await adjusted.data();
  const sorted = Array.from(values)
    .map((v, i) => ({ v, i }))
    .sort((a, b) => b.v - a.v)
    .slice(0, topKFilter);
  const topIndices = sorted.map(o => o.i);
  const topValues = sorted.map(o => o.v);
  const topLogits = tf.tensor1d(topValues);
  const sampled = tf.multinomial(topLogits, 1);
  const sampledIdx = (await sampled.data())[0];
  const wordIdx = topIndices[sampledIdx];
  input.dispose(); logits.dispose(); adjusted.dispose(); topLogits.dispose(); sampled.dispose();
  return vocab.idx2word[wordIdx];
}

function App() {
  const [modelData, setModelData] = useState(null);
  const [trainingData, setTrainingData] = useState(null);
  const [isTraining, setIsTraining] = useState(false);
  const [inputText, setInputText] = useState('');
  const [temperature, setTemperature] = useState(DEFAULT_TEMPERATURE);
  const [topKFilter, setTopKFilter] = useState(DEFAULT_TOPK);
  const [suggestions, setSuggestions] = useState([]);
  const autoRef = useRef(null);
  const inputTextRef = useRef(null);


  useEffect(() => {
    async function run() {
      if (process.env.NODE_ENV === 'test') return;
      const data = await loadData();
      // keep sequences and labels for optional training later
      setTrainingData({ sequences: data.sequences, labels: data.labels });
      const loaded = await tf.loadLayersModel(process.env.PUBLIC_URL + '/next-word-model.json');
      setModelData({ model: loaded, vocab: data.vocab });
    }
    run();
  }, []);

  if (!modelData) return <div>Loading model...</div>;
  const { model, vocab } = modelData;

  const predictNext = async (text) => {
    const tokens = tokenize(text || inputText);
    if (tokens.length < SEQ_LEN) return [];
    const seq = tokens.slice(-SEQ_LEN).map(w => vocab.word2idx[w] ?? 0);
    const inputTensor = tf.tensor2d([seq]);
    const logits = model.predict(inputTensor);
    inputTensor.dispose();
    const logProbs = tf.log(logits);
    const adjusted = tf.div(logProbs, temperature);
    const probsTensor = tf.softmax(adjusted);
    const probs = await probsTensor.data();
    const suggestions = Array.from(probs)
      .map((p, i) => ({ word: vocab.idx2word[i], prob: p }))
      .sort((a, b) => b.prob - a.prob)
      .slice(0, SUGGESTION_COUNT);
    logits.dispose(); logProbs.dispose(); adjusted.dispose(); probsTensor.dispose();
    return suggestions;
  };

  const handlePredict = async () => {
    const next = await predictNext();
    setSuggestions(next);
  };

  const handleNext = async () => {
    const tokens = tokenize(inputText);
    if (tokens.length < SEQ_LEN) return;
    const seq = tokens.slice(-SEQ_LEN).map(w => vocab.word2idx[w] ?? 0);
    const sampledWord = await sampleNextWord(model, seq, vocab, temperature, topKFilter);
    setInputText(prev => `${prev} ${sampledWord}`);
    setSuggestions([]);
  };

  const handleAuto = () => {
    let count = 0;
    autoRef.current = setInterval(async () => {
      const tokens = tokenize(inputTextRef.current.value);
      if (tokens.length < SEQ_LEN || count >= 10) {
        clearInterval(autoRef.current);
        return;
      }
      const seq = tokens.slice(-SEQ_LEN).map(w => vocab.word2idx[w] ?? 0);
      const w = await sampleNextWord(model, seq, vocab, temperature, topKFilter);
      setInputText(prev => `${prev} ${w}`);
      count += 1;
    }, 500);
  };

  const handleStop = () => {
    if (autoRef.current) clearInterval(autoRef.current);
  };

  const handleReset = () => {
    setInputText('');
    setSuggestions([]);
    handleStop();
  };

  const handleTrain = async () => {
    if (!trainingData) return;
    setIsTraining(true);
    const { sequences, labels } = trainingData;
    const trained = await trainModel({ sequences, labels, vocab: modelData.vocab });
    setModelData(trained);
    setIsTraining(false);
  };

  const handleDownload = async () => {
    if (model) await model.save('downloads://next-word-model');
  };

  return (
    <div className="p-4 max-w-4xl mx-auto text-center space-y-4">
      <h2 className="text-2xl font-bold">Next Word Prediction Demo</h2>
      <textarea
        className="w-full border rounded p-2"
        ref={inputTextRef}
        value={inputText}
        onChange={e => setInputText(e.target.value)}
        rows={4}
      />
      <p>Please enter at least <b>{SEQ_LEN} words</b> to get predictions!</p>
      <div className="flex flex-col sm:flex-row justify-center gap-4">
        <label className="flex items-center gap-2">
          Temperature: {temperature.toFixed(1)}
          <input type="range" min="0.1" max="2" step="0.1" value={temperature} onChange={e => setTemperature(parseFloat(e.target.value))} />
        </label>
        <label className="flex items-center gap-2">
          Top-K:
          <input className="border p-1 w-16" type="number" min="1" max="50" value={topKFilter} onChange={e => setTopKFilter(parseInt(e.target.value, 10)||1)} />
        </label>
      </div>
      <div className="flex flex-wrap justify-center gap-2">
        <button className="bg-blue-500 text-white px-3 py-1 rounded hover:bg-blue-600" onClick={handlePredict}>Vorhersage</button>
        <button className="bg-green-500 text-white px-3 py-1 rounded hover:bg-green-600" onClick={handleNext}>Weiter</button>
        <button className="bg-purple-500 text-white px-3 py-1 rounded hover:bg-purple-600" onClick={handleAuto}>Auto</button>
        <button className="bg-gray-500 text-white px-3 py-1 rounded hover:bg-gray-600" onClick={handleStop}>Stopp</button>
        <button className="bg-red-500 text-white px-3 py-1 rounded hover:bg-red-600" onClick={handleReset}>Reset</button>
        <button className="bg-yellow-500 text-white px-3 py-1 rounded hover:bg-yellow-600" onClick={handleTrain} disabled={isTraining}>Trainieren</button>
        <button className="bg-indigo-500 text-white px-3 py-1 rounded hover:bg-indigo-600" onClick={handleDownload}>Download Model</button>
      </div>
      <ul className="space-y-1">
        {suggestions.map((s,i)=>(
          <li key={i} className="cursor-pointer hover:bg-gray-100 p-1 rounded" onClick={()=>setInputText(prev=>`${prev} ${s.word}`)}>
            {s.word} ({s.prob.toFixed(3)})
          </li>
        ))}
      </ul>
      <Documentation />
    </div>
  );
}

export default App;

